import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { format } from 'oxfmt';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = fs.readFileSync(path.join(root, 'schema/protocol.json'), 'utf8');
const schema = JSON.parse(source);
const fingerprint = createHash('sha256').update(JSON.stringify(schema)).digest().readUInt32LE();
const banner =
  '// Generated by engine/tools/generate-schema.mjs. Edit engine/schema/protocol.json.\n';
const groups = Object.entries(schema).filter(([, value]) => typeof value === 'object');
const numbers = Object.entries(schema).filter(([, value]) => typeof value === 'number');
// Alternative operator tokens are keywords in C++, but remain public JS keys.
const cppIdentifier = (key) => (key === 'xor' ? 'xor_' : key);
const cpp =
  banner +
  '#pragma once\n#include <cstdint>\nnamespace nelyx::v2::wire {\n' +
  `inline constexpr uint32_t schema = ${fingerprint}u;\n` +
  numbers.map(([key, value]) => `inline constexpr uint32_t ${key} = ${value}u;`).join('\n') +
  '\n' +
  groups
    .map(
      ([group, values]) =>
        `namespace ${group} {\n` +
        Object.entries(values)
          .map(([key, value]) => `inline constexpr uint32_t ${cppIdentifier(key)} = ${value}u;`)
          .join('\n') +
        '\n}',
    )
    .join('\n') +
  '\n}\n';
const config = JSON.parse(fs.readFileSync(path.resolve(root, '../../.oxfmtrc.json'), 'utf8'));
delete config.$schema;
const formatted = await format(
  'schema.ts',
  banner +
    `export const protocol = ${JSON.stringify({ ...schema, schema: fingerprint }, null, 2)} as const;\n`,
  config,
);
if (formatted.errors.length) throw new Error('Engine schema formatting failed');
const ts = formatted.code;
const outputs = [
  [path.join(root, 'core/protocol/schema.hpp'), cpp],
  [path.resolve(root, '../runtime/engine-client/schema.ts'), ts],
];
for (const [file, wanted] of outputs) {
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== wanted)
      throw new Error('Generated engine schema differs: ' + file);
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, wanted);
  }
}
